def zigzag(grid):
    m, n = len(grid), len(grid[0])
    out = []
    for d in range(m + n - 1):
        cells = []
        for r in range(max(0, d - n + 1), min(m, d + 1)):
            cells.append(grid[r][d - r])
        if d % 2 == 0:
            cells.reverse()
        out.extend(cells)
    return out

