vector<int> zigzag(const vector<vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    vector<int> out;
    for (int d = 0; d < m + n - 1; d++) {
        vector<int> cells;
        for (int r = max(0, d - n + 1); r < min(m, d + 1); r++) {
            cells.push_back(grid[r][d - r]);
        }
        if (d % 2 == 0) reverse(cells.begin(), cells.end());
        out.insert(out.end(), cells.begin(), cells.end());
    }
    return out;
}

