static int min2(int a, int b) { return a < b ? a : b; }

// Writes one sum per ring to sums and returns how many rings there are.
int ringSums(const int* grid, int m, int n, long long* sums) {
    int rings = (min2(m, n) + 1) / 2;
    for (int k = 0; k < rings; k++) sums[k] = 0;
    for (int r = 0; r < m; r++) {
        for (int c = 0; c < n; c++) {
            int k = min2(min2(r, c), min2(m - 1 - r, n - 1 - c));
            sums[k] += grid[r * n + c];
        }
    }
    return rings;
}
